import time
from acme import RateLimitError  # import path assumed; docs only name the class

DEFAULT_RETRY_DELAY = 5  # seconds, used when the server gives no Retry-After

def call_with_retry(request_fn, max_attempts=3):
    for attempt in range(max_attempts):
        try:
            return request_fn()
        except RateLimitError as err:
            if attempt == max_attempts - 1:
                raise
            delay = getattr(err, "retry_after_seconds", None) or DEFAULT_RETRY_DELAY
            time.sleep(delay)
